values
  ('42dc4e1e-955c-49c3-a235-4a3b43228b85', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', null, 'topic'::public.curated_course_node_type, 'What Contemporary Social Theory Does', 'This opening topic frames theory as a toolkit for explaining social order, conflict, meaning, power, identity, and change. Students learn to read theory as argument, vocabulary, method, and critique.', 0),
  ('035529ab-4771-4f6f-8fda-bd985db7e3ca', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '42dc4e1e-955c-49c3-a235-4a3b43228b85', 'subtopic'::public.curated_course_node_type, 'Theory as explanation and critique', 'Students learn why theory matters for seeing social patterns that common sense often hides.', 0),
  ('bb98fa86-a7d0-4a9b-aa6f-d74bf0c27800', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '035529ab-4771-4f6f-8fda-bd985db7e3ca', 'concept'::public.curated_course_node_type, 'Concepts, mechanisms, and claims', null, 0),
  ('39746c1b-cdfc-4598-be42-1f78d5d92820', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '035529ab-4771-4f6f-8fda-bd985db7e3ca', 'concept'::public.curated_course_node_type, 'Normative critique and empirical explanation', null, 1),
