  ('00ee27a6-32b5-4c1d-9b7c-a3fedff8304b', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '42dc4e1e-955c-49c3-a235-4a3b43228b85', 'subtopic'::public.curated_course_node_type, 'Reading difficult theory', 'Theory becomes manageable when students learn how to track terms, arguments, assumptions, and stakes.', 1),
