  ('e4c583d9-8818-41e3-a9b2-73ae2b9d9a59', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '00ee27a6-32b5-4c1d-9b7c-a3fedff8304b', 'concept'::public.curated_course_node_type, 'Passage annotation and seminar questions', null, 2),
  ('33afff2a-31df-47a7-8977-8ad285a6db0a', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '42dc4e1e-955c-49c3-a235-4a3b43228b85', 'subtopic'::public.curated_course_node_type, 'Theory and contemporary problems', 'Students connect abstract frameworks to concrete social issues.', 2),
  ('05516230-736e-4a16-b3f8-212d11f54de4', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '33afff2a-31df-47a7-8977-8ad285a6db0a', 'concept'::public.curated_course_node_type, 'Inequality, identity, and institutions', null, 0),
  ('fe93a1d4-cf22-4eea-9293-e2091490fc02', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '33afff2a-31df-47a7-8977-8ad285a6db0a', 'concept'::public.curated_course_node_type, 'Media, culture, and technology', null, 1),
  ('7289e55a-aac1-457d-be22-78a8d5c7fb1a', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '33afff2a-31df-47a7-8977-8ad285a6db0a', 'concept'::public.curated_course_node_type, 'Globalization, climate, and social change', null, 2),
  ('ce2b4f28-36d5-41c9-9d69-bc38d6ba06c9', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', null, 'topic'::public.curated_course_node_type, 'Classical Foundations and Contemporary Problems', 'Contemporary theory grows from classical debates while revising their blind spots. This section links Marx, Durkheim, Weber, Simmel, Du Bois, Martineau, and Gilman to modern theoretical problems.', 1),
  ('c3f41393-ea6e-4354-81c6-14d53ee4444c', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'ce2b4f28-36d5-41c9-9d69-bc38d6ba06c9', 'subtopic'::public.curated_course_node_type, 'Classical continuities', 'Students see how contemporary theory inherits problems of capitalism, solidarity, rationalization, modernity, race, gender, and power.', 0),
  ('edc5c207-f97e-41fd-9d67-3fe7621ddd01', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'c3f41393-ea6e-4354-81c6-14d53ee4444c', 'concept'::public.curated_course_node_type, 'Marx and capitalism', null, 0),
  ('e129f39c-5999-4873-81dc-bf10b9ad1ed8', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'c3f41393-ea6e-4354-81c6-14d53ee4444c', 'concept'::public.curated_course_node_type, 'Durkheim and social integration', null, 1),
  ('c394f0c1-d482-4d9d-bb96-c238edbb5605', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'c3f41393-ea6e-4354-81c6-14d53ee4444c', 'concept'::public.curated_course_node_type, 'Weber and rationalization', null, 2),
  ('13470aaf-4a73-4ba2-9a95-6d0555bd5ee0', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'ce2b4f28-36d5-41c9-9d69-bc38d6ba06c9', 'subtopic'::public.curated_course_node_type, 'Recovering excluded theorists', 'A world-class theory course treats Du Bois, Martineau, Gilman, and other marginalized thinkers as central rather than supplemental.', 1),
  ('ea8f87cb-618a-4235-84bd-18903e9cc3a4', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '13470aaf-4a73-4ba2-9a95-6d0555bd5ee0', 'concept'::public.curated_course_node_type, 'Du Bois and the color line', null, 0),
  ('5cea9c07-30f0-49bd-88e3-2173aecf9af5', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '13470aaf-4a73-4ba2-9a95-6d0555bd5ee0', 'concept'::public.curated_course_node_type, 'Martineau and gendered method', null, 1),
  ('9a30fb90-e3f3-4dae-8dbf-4c5ef4ac4d14', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '13470aaf-4a73-4ba2-9a95-6d0555bd5ee0', 'concept'::public.curated_course_node_type, 'Gilman and political economy of gender', null, 2),
  ('d83c378a-499e-4497-ad07-8ce1593468ef', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'ce2b4f28-36d5-41c9-9d69-bc38d6ba06c9', 'subtopic'::public.curated_course_node_type, 'From classical to contemporary', 'Students learn how later theorists keep, reject, or transform classical assumptions.', 2),
  ('38501f4a-9871-4f68-ad85-94a0a323891f', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'd83c378a-499e-4497-ad07-8ce1593468ef', 'concept'::public.curated_course_node_type, 'Modernity and its critics', null, 0),
  ('3128982d-9e1b-4960-bffb-e1d76b0d3037', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'd83c378a-499e-4497-ad07-8ce1593468ef', 'concept'::public.curated_course_node_type, 'Structure versus agency', null, 1),
  ('968412d6-d3de-4700-95a4-4740f2dfc37e', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'd83c378a-499e-4497-ad07-8ce1593468ef', 'concept'::public.curated_course_node_type, 'Macro, meso, and micro levels', null, 2),
  ('615ed7ac-33c2-4b35-b177-09c2209571f4', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', null, 'topic'::public.curated_course_node_type, 'Structural Functionalism and Social Systems', 'Functionalism asks how social institutions create order, integration, and stability. Students study both the power and limits of system-level explanation.', 2),
  ('dc7a58a7-a6c1-4721-8370-09903f5c5cc5', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '615ed7ac-33c2-4b35-b177-09c2209571f4', 'subtopic'::public.curated_course_node_type, 'Parsons and social order', 'Parsons helps students understand society as interdependent systems of norms, roles, and institutions.', 0),
  ('ed080a24-78a5-456f-9d3d-453a76187ccb', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'dc7a58a7-a6c1-4721-8370-09903f5c5cc5', 'concept'::public.curated_course_node_type, 'AGIL framework', null, 0),
  ('020f6dd3-0c33-4e0a-ad1c-e561e94e0d52', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'dc7a58a7-a6c1-4721-8370-09903f5c5cc5', 'concept'::public.curated_course_node_type, 'Role expectations', null, 1),
  ('be360b0a-c2ce-430d-9f92-0ba6ebed49e2', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'dc7a58a7-a6c1-4721-8370-09903f5c5cc5', 'concept'::public.curated_course_node_type, 'Value consensus', null, 2),
  ('7d5bc6ff-98c4-47b4-bd3d-e314b54af46c', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '615ed7ac-33c2-4b35-b177-09c2209571f4', 'subtopic'::public.curated_course_node_type, 'Merton and middle-range theory', 'Merton makes functional analysis more precise by focusing on unintended consequences and measurable social processes.', 1),
  ('628c9ef2-d586-456c-9c72-8bffc90397a0', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '7d5bc6ff-98c4-47b4-bd3d-e314b54af46c', 'concept'::public.curated_course_node_type, 'Manifest and latent functions', null, 0),
  ('b0b45e49-c889-4e26-bef9-7f10217ce34e', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '7d5bc6ff-98c4-47b4-bd3d-e314b54af46c', 'concept'::public.curated_course_node_type, 'Dysfunctions', null, 1),
  ('725a9131-686d-4161-ad46-176ccb164494', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '7d5bc6ff-98c4-47b4-bd3d-e314b54af46c', 'concept'::public.curated_course_node_type, 'Middle-range explanation', null, 2),
  ('3c0c889a-ae21-41f9-9630-d61b73de2e16', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '615ed7ac-33c2-4b35-b177-09c2209571f4', 'subtopic'::public.curated_course_node_type, 'Critiques of functionalism', 'Students learn why functionalism can understate conflict, domination, and historical change.', 2),
  ('b54de1a5-4e96-40de-b0f3-f6078586179d', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '3c0c889a-ae21-41f9-9630-d61b73de2e16', 'concept'::public.curated_course_node_type, 'Conservatism critique', null, 0),
  ('215a280f-b422-4c59-a75e-9948344206b5', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '3c0c889a-ae21-41f9-9630-d61b73de2e16', 'concept'::public.curated_course_node_type, 'Power and inequality blind spots', null, 1),
  ('f996e41c-ed7f-46fa-9ff2-357b4416e47e', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '3c0c889a-ae21-41f9-9630-d61b73de2e16', 'concept'::public.curated_course_node_type, 'Static versus dynamic models', null, 2),
  ('2ab69be3-b0c8-4d86-8a8d-6b7a659ffd56', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', null, 'topic'::public.curated_course_node_type, 'Conflict Theory and Neo-Marxism', 'Conflict theory centers domination, exploitation, contradiction, and struggle. Students learn to analyze capitalism, class, state power, ideology, and social change through neo-Marxist and critical traditions.', 3);
