  ('e57311f0-c77b-4dc1-83ff-a05bdbeeb4ea', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '2b590db4-29c9-45b0-a22d-b9e35f355912', 'concept'::public.curated_course_node_type, 'World-systems and dependency thinking', null, 2),
