  ('ad479a67-3dd0-4e69-8b13-2fffc252ad63', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'fcd640f3-795c-41ca-843b-f48a0cc609f6', 'concept'::public.curated_course_node_type, 'Social reproduction', null, 1),
