  ('b05c6642-cfc6-4976-b3b6-d2eaa300c08b', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '2e107e61-7776-4a5b-9b79-2dfedfb92c84', 'concept'::public.curated_course_node_type, 'Mind, self, and society', null, 2),
