  ('409cc6e8-7827-4cf3-bd71-0d611a3fc465', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', null, 'topic'::public.curated_course_node_type, 'Phenomenology, Ethnomethodology, and Everyday Order', 'Phenomenology and ethnomethodology ask how ordinary social reality becomes taken for granted. Students study background knowledge, rules, interactional repair, and the production of everyday order.', 5),
  ('c80ad5b2-b946-4094-8d7f-66439a10c798', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '409cc6e8-7827-4cf3-bd71-0d611a3fc465', 'subtopic'::public.curated_course_node_type, 'Phenomenology of the social world', 'Students examine lived experience and common-sense knowledge as foundations of social reality.', 0),
  ('21a8353f-e12e-4d0c-ae38-97ebe550b78a', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'c80ad5b2-b946-4094-8d7f-66439a10c798', 'concept'::public.curated_course_node_type, 'Lifeworld', null, 0),
