  ('39699486-8234-41e1-95de-2b10f27fdc4c', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'c80ad5b2-b946-4094-8d7f-66439a10c798', 'concept'::public.curated_course_node_type, 'Intersubjectivity', null, 2),
  ('8914af06-6ced-40fa-9f85-487a75ca1820', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '409cc6e8-7827-4cf3-bd71-0d611a3fc465', 'subtopic'::public.curated_course_node_type, 'Ethnomethodology', 'Ethnomethodology reveals the hidden methods people use to make situations intelligible.', 1),
  ('b1e7f560-2530-4d5d-89b6-63b80f62071c', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '8914af06-6ced-40fa-9f85-487a75ca1820', 'concept'::public.curated_course_node_type, 'Indexicality', null, 0),
