  ('3505481e-55d7-4374-9067-1349286deb26', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'b021ca87-8087-4788-a928-92b52b4e13a3', 'concept'::public.curated_course_node_type, 'Turn-taking', null, 0),
