  ('f5ad5db8-3d67-48f3-839d-3a34e07693b4', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', null, 'topic'::public.curated_course_node_type, 'Feminist Theory, Gender, and Sexuality', 'Feminist theory analyzes gender as a social structure, identity, embodied experience, and field of power. Students learn how feminist frameworks transform assumptions about knowledge, labor, family, sexuality, and inequality.', 7),
