  ('0d05257d-0f80-4ca3-a831-7c9b2771ca4d', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'e870ecc3-2125-4d77-bc59-870973cf26b3', 'concept'::public.curated_course_node_type, 'Standpoint theory', null, 0),
