  ('088b9c0c-a606-48f5-9bfa-4ea3423abfc8', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'e870ecc3-2125-4d77-bc59-870973cf26b3', 'concept'::public.curated_course_node_type, 'Objectivity and reflexivity', null, 2),
