  ('5580e55e-68d0-44e4-a5d6-1e1f1a91c94b', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'f5ad5db8-3d67-48f3-839d-3a34e07693b4', 'subtopic'::public.curated_course_node_type, 'Queer and sexuality theory', 'Queer theory challenges fixed categories and examines norms governing desire, identity, and legitimacy.', 2),
