  ('108a2f41-5bad-4878-be19-7073c9cf1804', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '5580e55e-68d0-44e4-a5d6-1e1f1a91c94b', 'concept'::public.curated_course_node_type, 'Sexual citizenship', null, 2),
