  ('651a3b9a-3333-440d-80ff-931d475b1995', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '38837697-6fa0-4e36-82eb-7f04ca5f61db', 'concept'::public.curated_course_node_type, 'Racialization', null, 0),
