  ('b7d4d0f1-e6ad-49e8-8afd-a1e2021eaa12', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '186b52ef-147a-49db-bb45-65257030e48a', 'concept'::public.curated_course_node_type, 'Coloniality of power', null, 1),
  ('b38e46d6-699a-482c-b261-b0fdecf39a62', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '186b52ef-147a-49db-bb45-65257030e48a', 'concept'::public.curated_course_node_type, 'Epistemic justice and decolonizing knowledge', null, 2),
