  ('6d95737f-8a3c-4a99-b25c-dd1e1188ba94', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', null, 'topic'::public.curated_course_node_type, 'Bourdieu: Habitus, Capital, Field, and Practice', 'Bourdieu offers one of the strongest bridges between structure and agency. Students learn how dispositions, resources, fields, and symbolic power reproduce inequality through ordinary practice.', 10),
  ('0eeae38a-5116-4953-b0a7-e1ae409ab05f', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '6d95737f-8a3c-4a99-b25c-dd1e1188ba94', 'subtopic'::public.curated_course_node_type, 'Habitus and practice', 'Habitus explains how social history becomes embodied as durable tendencies and practical sense.', 0),
  ('d94b7d25-7893-4d24-a22f-652d7e9dedcc', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '0eeae38a-5116-4953-b0a7-e1ae409ab05f', 'concept'::public.curated_course_node_type, 'Disposition', null, 0),
