  ('538578f5-bb40-4bec-abb3-3069c4818210', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '0eeae38a-5116-4953-b0a7-e1ae409ab05f', 'concept'::public.curated_course_node_type, 'Embodiment and taste', null, 2),
