  ('75c52a04-1c75-484b-b0ee-b8ca6f8d214d', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '163bba07-4eb1-4628-bd9d-84245910b878', 'concept'::public.curated_course_node_type, 'Doxa and misrecognition', null, 1),
