  ('a0b594e5-32d4-4ef0-96b4-16e0444be76b', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'f820cc33-2697-469f-9851-71db20809c85', 'concept'::public.curated_course_node_type, 'Core-periphery hierarchy', null, 0),
  ('6ea48ac4-f9ee-4371-99a1-530509d95fa6', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'f820cc33-2697-469f-9851-71db20809c85', 'concept'::public.curated_course_node_type, 'Unequal exchange', null, 1),
