  ('4acff12c-18b3-4ba8-be34-6bacccc2a162', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '5b232a06-b7f6-45e7-a6cd-beee0a004086', 'concept'::public.curated_course_node_type, 'Diaspora', null, 0),
