  ('52e6d6c6-ec09-420c-8a9b-fbfe7948addd', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '4f5faf4e-9e05-4bf2-b10f-d7881d81da85', 'concept'::public.curated_course_node_type, 'Global governance', null, 2),
