  ('a4c672ef-03b2-41be-86ee-516f492500d6', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', 'c11226f8-e50b-461e-a0c7-34fe6664a727', 'concept'::public.curated_course_node_type, 'False consciousness debates', null, 0),
