  ('8be2a347-41c3-494e-9ee4-42efdea9412f', 'c2d3e4f5-6a7b-4d92-9e12-3f4a5b6c7d22', '3684a5da-c3b2-46c3-be7c-ba8958a40daf', 'concept'::public.curated_course_node_type, 'Concept definition', null, 0),
